def minPath(grid, k):
    from heapq import heappush, heappop

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def neighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    # Priority queue for paths, starting with all single-cell paths
    pq = []
    for i in range(N):
        for j in range(N):
            heappush(pq, (grid[i][j], [(i, j)]))

    # Perform a modified Dijkstra's algorithm to find the lexicographically smallest path
    while pq:
        current_value, path = heappop(pq)
        if len(path) == k:
            return [grid[x][y] for x, y in path]

        last_x, last_y = path[-1]
        for nx, ny in neighbors(last_x, last_y):
            new_path = path + [(nx, ny)]
            new_value = current_value + grid[nx][ny]
            heappush(pq, (new_value, new_path))

